  let planData={};
let planChoice={category:'',currency:'',capital:''};
function visiblePlan(p){return !p.display_excluded&&p.initial_capital!=null&&!!p.capital_currency&&![16666,33333,66666,133333,266666].includes(Number(p.initial_capital));}
function capitalKey(p){return `${p.capital_currency==='USD_display'?'USD':p.capital_currency} ${p.initial_capital}`;}
function amountLabel(value,currency){if(value===null||value===undefined||value==='')return 'Not confirmed';const n=Number(value);if(!Number.isFinite(n))return esc(value);const f=x=>x.toLocaleString('en',{maximumFractionDigits:6});if(currency==='JPY')return `JPY ${f(n)}`;if(currency==='USD'||currency==='USD_display')return n%1000===0?`$${f(n/1000)}K`:`$${f(n)}`;return `${esc(currency||'Currency unconfirmed')} ${f(n)}`;}
function priceLabel(value,currency){if(value==null||value===''||!currency)return '—';const c=currency==='USD_display'?'USD':currency;return esc(c||'Currency unconfirmed')+' '+esc(Number.isFinite(Number(value))?Number(value).toLocaleString('en',{maximumFractionDigits:6}):value);}
function planActive(){return Object.values(planChoice).some(Boolean);}
function matchingPlans(id){return (planData[id]||[]).filter(visiblePlan).filter(p=>(!planChoice.category||p.category===planChoice.category)&&(!planChoice.currency||capitalKey(p).startsWith(planChoice.currency+' '))&&(!planChoice.capital||capitalKey(p)===planChoice.capital));}
function planPrice(p){return `${esc(p.plan_name)} ／ ${amountLabel(p.initial_capital,p.capital_currency)} ／ Listed price <b>${priceLabel(p.display_price,p.price_currency)}</b>`;}
function planPrices(id){const ps=matchingPlans(id),n=new Set(ps.map(p=>p.plan_name)).size;const preview=planChoice.capital?ps.slice(0,2).map(p=>'<div class="plan-price-group-v168"><strong class="plan-price-name-v168">'+esc(p.plan_name)+'</strong><span>'+priceLabel(p.display_price,p.price_currency)+'</span></div>').join(''):'';return '<span class="plan-price-count-v168">Matching plans: '+n+'</span>'+preview+'<button type="button" class="plan-expand-v169" aria-haspopup="dialog" aria-expanded="false">View plans, prices and key rules ↗</button>';}
function ruleValue(v){if(v==null||v==='')return 'Not confirmed';if(Array.isArray(v))return v.length?v.map(ruleValue).join(' / '):'Not confirmed';if(typeof v==='object')return esc(JSON.stringify(v));return esc(({static:'Static',trailing:'Trailing',true:'Allowed',false:'Not allowed'})[String(v)]??v);}
function percentValue(v){return v==null?'Not confirmed':Array.isArray(v)?v.map(x=>ruleValue(x)+'%').join(' → '):ruleValue(v)+'%';}
function planMatrix(id){
 const lifted=document.querySelector("#detail-root")?commonRuleData200(id).common:[];
 const groups=new Map();matchingPlans(id).forEach(p=>{const key=p.plan_name+'|'+capitalKey(p).split(' ')[0];if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);});
 const fields=[['Fee (listed price)','price'],['Profit target (evaluation)','profit_target'],['Maximum DD / calculation','max_dd'],['Daily DD / calculation','daily_dd'],['Fee refund after passing','refund_after_pass'],['Funded profit target','funded_profit_target'],['Maximum lots','max_lots'],['EAs / automation','ea'],['Copy trading','copy'],['VPS restrictions','vps'],['IP rules','ip'],['Minimum profitable days','minimum_profit_days'],['Profit split','profit_share'],['Payout request interval','payout_interval'],['Payout caps / minimum','payout_limit'],['Leverage','leverage'],['Consistency','consistency']];
 const renderCell=(f,key)=>{if(!f)return '<span class="plan-omitted-v174" aria-label="Not listed; this does not mean unrestricted">—</span>';const text=esc(f.text_en);const refs=f.sources.filter(s=>s.source_url.startsWith('https://'));const amount=key==='price'?f.text_en.match(/(?:USDC|USD|JPY|EUR|GBP)\s*[0-9,]+(?:\.[0-9]+)?/):null;const content=amount?'<strong class="plan-price-main-v174">'+esc(amount[0])+'</strong><details class="plan-price-terms-v174"><summary>Fee conditions</summary><p>'+text+'</p></details>':'<div class="plan-rule-text-v174">'+text+'</div>';return content+(refs.length?'<details class="plan-citation-v174"><summary>Sources / checked date</summary>'+refs.map((s,i)=>'<a href="'+esc(s.source_url)+'" target="_blank" rel="noopener noreferrer">Official '+(i+1)+' ↗</a> <time>'+esc(s.checked_on)+'</time>').join('<br>')+'</details>':'');};
 return [...groups].map(([_,rows])=>{rows.sort((a,b)=>a.initial_capital-b.initial_capital);const name=rows[0].plan_name;let body='';for(const [label,key] of fields){if(lifted.includes(key))continue;const vals=rows.map(p=>p.approved_display?.[key]||null);if(vals.every(v=>!v)&&!(key==='price'&&rows.every(p=>p.display_price==null)))continue;const same=vals.every(v=>JSON.stringify(v)===JSON.stringify(vals[0]));body+='<tr'+(key==='price'?' class="plan-fee-v169"':'')+'><th scope="row">'+label+'</th>'+(same?'<td colspan="'+rows.length+'">'+renderCell(vals[0],key)+'</td>':vals.map(v=>'<td>'+renderCell(v,key)+'</td>').join(''))+'</tr>';}
 return '<section class="plan-family-v169"><h4>'+esc(name)+'</h4>'+officialPlanNotice(rows)+'<p class="plan-scroll-hint-v174">Compare capital sizes <span>← Scroll horizontally →</span></p><div class="plan-matrix-scroll-v169" tabindex="0" role="region" aria-label="'+esc(name)+' capital-size comparison"><table class="plan-matrix-v169" style="min-width:'+Math.max(600,160+rows.length*185)+'px!important"><thead><tr><th scope="col">Initial capital</th>'+rows.map(p=>'<th scope="col">'+amountLabel(p.initial_capital,p.capital_currency)+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>'+(document.querySelector('#detail-root')?'':specialRules(rows))+'</section>';}).join('')||'<p>No listed plans match these filters.</p>';
}

