 const rules=[...new Set(rows.flatMap(p=>[...(p.rule_source_urls||[]),...(p.display_rule_sources||[]).map(s=>s.source_url),...(p.special_rules||[]).map(s=>s.source_url)]))].filter(u=>typeof u==='string'&&u.startsWith('https://'));
