 const esc200=esc, t=["Common rules and prohibited practices", "Special rules to check carefully", "Conditions shared by the listed plans. Check each item for evaluation/funded stages and add-on exceptions.", "Official source", "Checked", "Applicable plans"], labels=["EA / automation", "Copy trading", "VPS restrictions", "IP rules"],keys=['ea','copy','vps','ip'];
