 let s=common.length?'<section class="common-rules-v200"><h4>'+t[0]+'</h4><p>'+t[2]+'</p><dl>'+common.map(k=>{const x=rows[0].approved_display[k];return '<div><dt>'+labels[keys.indexOf(k)]+'</dt><dd>'+esc200(x.text_en)+'<p>'+refs(x)+'</p></dd></div>';}).join('')+'</dl></section>':'';
 const groups=new Map();rows.forEach((p,index)=>(p.special_rules||[]).forEach(x=>{const key=x.title+x.text; if(!groups.has(key))groups.set(key,{x,names:new Set(),indices:new Set()});groups.get(key).names.add(p.plan_name);groups.get(key).indices.add(index);}));
 if(groups.size)s+='<section class="special-rules-v200"><h4>'+t[1]+'</h4>'+[...groups.values()].map(({x,names,indices})=>'<details class="legacy-special-v203"><summary>'+esc200(x.title)+'</summary><p>'+esc200(x.text)+'</p><small>'+t[5]+': '+(indices.size===rows.length ? "All listed plans (stage and add-on conditions are stated above)" : [...names].map(esc200).join(' / '))+'</small><p><a target="_blank" rel="noopener noreferrer" href="'+esc200(x.source_url)+'">'+t[3]+' ↗</a> <small>'+t[4]+' '+esc200(x.checked_on)+'</small></p></details>').join('')+'</section>';
 return s;
