const RULE_LINKS1019=[{"rule_id": "R6e4b8f40b1", "service_id": "fundedtradermarkets-fx-cfd", "reuse_title": null, "title": "1-Step Infinity: the static 3% floor moves to the initial balance after the first payout", "scope_text": "1-Step Infinity (Launchpad drop 1, limited-time sale) evaluation and funded accounts", "calculation": "Profit target 9%. Daily DD is 3% of the initial balance (subtracted from the higher of balance and equity at 17:00 ET each day). Max DD is a static 3% of the initial balance (the floor does not rise with profits). When the first payout after passing is approved, the floor moves once to the initial balance and then stays fixed. No consistency rule.", "consequence": "The balance you must keep after a payout (buffer) starts at initial balance +2% and rises by 2 pt every 3 approvals. From the 2nd payout, new profit of at least 1% of the initial balance above the post-payout balance is required. The per-payout cap is $250–$1,000 (by account size). 30% of the buffer is released every 15 approvals. Up to $40,000 in total per person. Accounts bought during a sale keep that sale’s rules for the life of the account.", "checked_on": "2026-10-19 (from our records)", "source_url": "https://fundedtradermarkets.com/faq"}, {"rule_id": "Rba92c7e84f", "service_id": "alpha-fx-cfd", "reuse_title": null, "title": "Profit removal for prohibited strategies depends on the violation type", "scope_text": "Trades and payout periods that fall under prohibited strategies", "calculation": "Depending on the type of violation, the profit from the trades concerned or all profit in that payout period is removed. This does not mean every violation always forfeits all profit.", "consequence": "Payout of the remaining balance is also postponed.", "source_url": "https://help.alphacapitalgroup.uk/en/articles/6934275-what-are-prohibited-trading-strategies", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "Rf68f95d35e", "service_id": "alpha-fx-cfd", "reuse_title": null, "title": "Combined allocation above 400K and measures on violation", "scope_text": "Combined allocation cap for Qualified accounts (separate from single account size)", "calculation": "The combined allocation cap is $400,000. If a violation is found, all accounts are closed and eligibility to withdraw profits is lost.", "consequence": "If passing an evaluation would take the combined Qualified allocation above $400,000, the company may treat that account as a refund of the purchase fee. Passing alone does not guarantee a funded account.", "source_url": "https://help.alphacapitalgroup.uk/en/articles/8804535-how-many-accounts-can-i-have-what-is-the-maximum-allocation-per-strategy", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "Rf8c9fedfaf", "service_id": "alpha-fx-cfd", "reuse_title": null, "title": "VPN/VPS require a fixed IP and prior notice", "scope_text": "VPN/VPS usage environment (separate from EA approval)", "calculation": "A VPN/VPS with a fixed IP may be used if notified in advance. Unnotified use may trigger security detection, account closure and a permanent ban.", "consequence": "The prior-notice requirement already existed. This history entry records the penalty being written down; it is not treated as a new notice obligation.", "source_url": "https://help.alphacapitalgroup.uk/en/articles/8420522-what-is-the-ip-rule-are-vpns-and-vpss-allowed", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "R998f0a0618", "service_id": "fundedtradermarkets-fx-cfd", "reuse_title": null, "title": "Gap trading across the rollover", "scope_text": "Gap trades across the rollover on all accounts", "calculation": "Covers trades opened within 5 minutes before the rollover and closed within 5 minutes after it. It does not mean all trading in each of those windows is prohibited.", "consequence": "Profit from such trades is not eligible for rewards.", "source_url": "https://fundedtradermarkets.com/faq/is-gap-trading-allowed", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "Re171faf425", "service_id": "fundedelite-fx-cfd", "reuse_title": null, "title": "Requested interviews must be booked and held within 5 business days", "scope_text": "When the company requests an interview during common identity checks or reviews", "calculation": "A video interview must be booked and held within 5 business days of the request. It is not a requirement for everyone every time.", "consequence": "Failing to respond can lead to refusal of pending payouts and account cancellation. Application to existing accounts is unconfirmed.", "source_url": "https://fundedelite.com/terms-and-conditions", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "R0fd7c885c5", "service_id": "fundedelite-fx-cfd", "reuse_title": null, "title": "The 4th payout becomes the starting balance of a live account", "scope_text": "Move to live after 4 consecutive payouts on the same funded account (English FAQ)", "calculation": "The 4th payout amount is not paid as a reward; it becomes the starting balance of a new live account. This is not a permanent forfeiture. Review may lead to an earlier move.", "consequence": "After the move there is no profit target, minimum profitable days or consistency rule. There is no payout waiting period or cycle, and the requested amount must cover the payment method fee. Whether the full transferred balance can be withdrawn immediately without trading is unconfirmed. Application to existing accounts is also unconfirmed, and the reply about the 1% risk rule on 10/14 is not reused for this change.", "source_url": "https://faq.fundedelite.com/en/articles/17566618", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "R7387a15e4f", "service_id": "fundedelite-fx-cfd", "reuse_title": null, "title": "Profitable days after passing standard evaluations: Japanese and English pages differ", "scope_text": "After passing 1-Step and 2-Step + Free Retry, LITE 1-Step and LITE 2-Step (excluding Instant types)", "calculation": "English FAQ: in principle 3 profitable days since the previous payout (since the start for the first payout). 1-Step + Free Retry requires at least 1% each day, 2-Step + Free Retry at least 0.5% (at least 1% for $200K and above), and LITE 1-Step and LITE 2-Step at least 1%. $300K accounts need 5 days. Japanese FAQ: in principle 3 trading days, with no profit target per day or overall. ¥50 million accounts need 5 days.", "consequence": "The company does not state which language version applies. Account currency, plan and stage are kept separate, and these conditions are not applied to the evaluation stage. Application to existing accounts is unconfirmed.", "source_url": "https://faq.fundedelite.com/en/articles/17437271-what-are-minimum-profitable-trading-days", "checked_on": "2026-10-18 (from our records)", "related_sources": ["https://faq.fundedelite.com/ja/articles/13645521", "https://faq.fundedelite.com/ja/articles/13645537", "https://faq.fundedelite.com/ja/articles/13645507", "https://faq.fundedelite.com/ja/articles/13645516"]}, {"rule_id": "R19b1aa5316", "service_id": "fundedelite-fx-cfd", "reuse_title": null, "title": "Profitable days for Instant types: Japanese and English pages differ", "scope_text": "Payout conditions for Instant / Instant Elite (separate from standard evaluations)", "calculation": "English FAQ: profitable days of at least 0.5% each changed from 3 to 4. $300K accounts and $300K/$400K Instant Elite need 5 days. Japanese instant-challenge FAQ: 3 profitable days of at least 0.5% each.", "consequence": "The company does not state which language version applies. The Japanese FAQ covers account sizes of ¥1.3 million to ¥20 million, so its 3-day condition is not applied wholesale to the larger English-page accounts. Application to existing accounts is unconfirmed.", "source_url": "https://faq.fundedelite.com/en/articles/17437271-what-are-minimum-profitable-trading-days", "checked_on": "2026-10-18 (from our records)", "related_sources": ["https://faq.fundedelite.com/ja/articles/13645500"]}, {"rule_id": "R53ad6f87c5", "service_id": "fundedelite-fx-cfd", "reuse_title": null, "title": "Plans eligible for a fee refund and recount after a soft breach", "scope_text": "Fee refund for 1-Step, 2-Step, LITE 1-Step and LITE 2-Step", "calculation": "On eligible plans the fee is refunded at the 3rd payout. The 3 payout cycles concerned must have no soft breach; a soft breach restarts the count.", "consequence": "Instant, Instant Elite, Flash Activation and Catalyst are not eligible for a refund. This does not mean refunds were abolished for all products. Application to existing accounts is unconfirmed.", "source_url": "https://faq.fundedelite.com/en/articles/17437366-do-i-get-my-challenge-fee-back", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "Re7593a6db4", "service_id": "fundednext-fx-cfd", "reuse_title": null, "title": "Program verification before reward approval or moving to Funded", "scope_text": "Before approval of rewards, moving to the Funded stage or related benefits", "calculation": "The company may carry out program verification, including interviews and additional documents. Meeting the evaluation targets alone does not guarantee reward eligibility; verification must be completed to the company's satisfaction. This does not assert that everyone is interviewed every time.", "consequence": "Failing verification may lead to refused rewards, account restrictions or termination. Enhanced due diligence for high-risk clients in the old terms is kept separate from the newly added verification before approving rewards.", "source_url": "https://fundednext.com/terms-of-service", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "Ra4b9300087", "service_id": "the5ers-fx-cfd", "reuse_title": "Verification interviews have a 5-business-day deadline", "title": "Verification interviews have a 5-business-day deadline", "scope_text": "When an interview is requested during identity checks or reviews", "calculation": "Under the current terms of 2026-10-12, the interview must be booked and completed within 5 business days of the request. What the 2026-03-01 history entry added was the booking deadline and the penalty; it does not mean a completion deadline was also added at that time.", "consequence": "Failing to respond in time leads to refusal of pending payouts, cancellation of all related accounts and termination of the relationship. Meeting the evaluation targets alone does not guarantee acceptance after passing.", "source_url": "https://the5ers.com/terms-and-conditions/", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "R34aa115eb5", "service_id": "the5ers-fx-cfd", "reuse_title": null, "title": "Termination conditions for statements and unauthorized disclosure of communications", "scope_text": "Contract conditions on statements and disclosure of communications (separate from prohibited trading methods)", "calculation": "Defaming the company, its employees or services in public, and disclosing internal communications, support tickets or private exchanges without permission, are grounds for terminating the contract.", "consequence": "The 2026-05-12 history entry added these grounds for termination. Not every sanction in the current terms is treated as having been added on that date.", "source_url": "https://the5ers.com/terms-and-conditions/", "checked_on": "2026-10-18 (from our records)"}, {"rule_id": "R1eae4360f6", "service_id": "fundednext-fx-cfd", "reuse_title": null, "title": "Permanent ban, withheld rewards and more for prohibited trading", "scope_text": "Prohibited trading covered by CFD terms 9.1 (tick scalping, etc.)", "calculation": "Besides account termination, refusal to advance to the next stage and a permanent ban, rewards may be withheld, suspended, adjusted, cancelled, refused or offset.", "consequence": "The confirmed difference is terms 9.1 between 2026-02-19 and 03-25. FAQ updates up to 10/9 are treated as the same matter, and the whole of terms 9.4 is not read as newly created.", "source_url": "https://fundednext.com/cfd-challenge-terms", "checked_on": "2026-10-18 (from our records)", "related_sources": ["https://help.fundednext.com/en/articles/11982604-is-tick-scalping-legal"]}, {"rule_id": "R300b3a7319", "service_id": "goat-fx-cfd", "reuse_title": null, "title": "Prohibited trading: no refund, and profits and unpaid payouts are not paid", "scope_text": "When program participation ends because of prohibited trading", "calculation": "Fees paid are not refunded, and profits and pending payouts are not paid.", "consequence": "Profit forfeiture already existed in the January 2026 version. This difference changes fee forfeiture from \"may\" to \"no refund\" and states explicitly that unpaid payouts are not paid. The source link was found broken in an earlier check and has not been rechecked.", "source_url": "https://help.goatfundedtrader.com/en/articles/10742118-what-are-prohibited-trading-practices", "checked_on": "2026-10-18 (from our records)"}];const SCOPED_IDS1019={"blueberry-fx-cfd": {"0": "R5765e19eeb"}};function scopedRows1019(id,base){if(!document.getElementById('rh-tab-tpl'))return base;const ids=SCOPED_IDS1019[id]||{};const linked=RULE_LINKS1019.filter(r=>r.service_id===id);return base.map((r,i)=>{const u=linked.find(x=>x.reuse_title===r.title);const b=ids[i]?{...r,rule_id:ids[i]}:r;return u?{...b,...u}:b;}).concat(linked.filter(r=>!r.reuse_title));}
function scopedSpecial209(id){const labels=["Special rule", "Applies to", "How it works", "Effect on payouts / account", "Official source", "Checked"];const base209=({"ftmo-fx-cfd":[{"title":"Manipulating trades to meet profitable-day conditions is prohibited","scope_text":"CFD evaluation and FTMO Account","calculation":"Splitting one trading idea across days to evade the 1-Step consistency requirement (the Consistency rule for new orders and merged accounts from 12 Oct 2026 09:00 GMT+3; the Best Day Rule for accounts from earlier orders) is prohibited. EAs and other tools must not generate more than 2,000 order, modification or cancellation requests per day.","consequence":"Consequences may include removing trades from history, evaluation failure, forfeiting rewards or terminating access or the contract. Hedging within one account is distinguished from manipulative hedging across accounts.","source_url":"https://ftmo.com/en/forbidden-trading-practices/","checked_on":"2026-10-05"},{"title":"Standard funded accounts: news restrictions also cover SL and TP executions","scope_text":"CFD Standard FTMO Account; excludes evaluation and Swing","calculation":"For affected instruments, opening, closing, pending-order execution and SL/TP execution are restricted within 2 minutes before and after specified releases. Holding an existing position is distinct from closing it during this window.","consequence":"An SL left on an existing position can still cause a breach if executed during the restricted window.","source_url":"https://ftmo.com/faq/can-i-trade-news/","checked_on":"2026-10-02"}],"the5ers-fx-cfd":[{"title":"Excessive risk and abrupt strategy changes are reviewed even within DD limits","scope_text":"Evaluation and funded stages","calculation":"Large changes in lot size or trade count versus usual or evaluation trading, concentration in correlated instruments and artificially creating profitable days are prohibited practices. HFT is described as mostly lasting seconds or less; this is not a universal minimum holding time.","consequence":"Trading patterns may be judged even without breaching a numerical limit. Consequences include termination, suspension, withholding profits or refunds, and permanent exclusion.","source_url":"https://the5ers.com/faqs/prohibited-trading-practices/","checked_on":"2026-10-05"},{"title":"Even self-developed EAs require prior written approval","scope_text":"Published automated-trading terms","calculation":"Prior written notice and written approval are required even for software you own or develop. The terms prohibit third-party-developed software.","consequence":"A general FAQ allowing EAs does not establish unconditional permission. Check product-specific copying exceptions, including Summer.","source_url":"https://the5ers.com/terms-and-conditions/","checked_on":"2026-10-02"},{"title":"Verification interviews have a 5-business-day deadline","scope_text":"When an interview is requested for verification or review","calculation":"The interview must be booked and completed within 5 business days of the request.","consequence":"Failure to comply may result in account or payout cancellation. Reaching the evaluation target alone does not guarantee acceptance into the funded stage.","source_url":"https://the5ers.com/terms-and-conditions/","checked_on":"2026-10-02"}],"fundednext-fx-cfd":[{"title":"Repeated risk breaches reduce the limit to 1%","scope_text":"FundedNext Account after passing","calculation":"Potential losses to SL and other relevant risk on concurrently open trades are aggregated, capped at 3% of initial capital. Splitting one idea into multiple orders is included. The first breach brings a warning and deduction of all breaching profits; the second permanently lowers the cap to 1% and deducts breaching profits.","consequence":"No reward is payable if deductions equal or exceed period profits. History is normally account-specific, but merged accounts inherit the stricter restrictions and history.","source_url":"https://help.fundednext.com/en/articles/14702245-what-are-the-risk-limits-on-a-fundednext-account","checked_on":"2026-10-05"},{"title":"Only 40% of news-window profits count; losses count in full","scope_text":"Affected instruments and specified major releases after passing","calculation":"Only 40% of profits from openings, closings or SL/TP executions within 5 minutes before or after a release are counted. This differs from normal news trading during evaluation.","consequence":"Losses remain in full; gains and losses are not adjusted symmetrically.","source_url":"https://help.fundednext.com/en/articles/10701685-is-news-trading-allowed-in-the-stellar-2-step-account","checked_on":"2026-10-02"},{"title":"50K and above: manual trading only, including assistance tools","scope_text":"CFD evaluation plans, by account size and platform","calculation":"Accounts of 50K or more require manual trading, including SL/TP and lot-adjustment tools. Smaller MT4/MT5 accounts require the applicable paid EA add-on for EA use. Automation on cTrader/MatchTrader is not allowed.","consequence":"Do not apply this indiscriminately to other products such as Stellar Instant. Complimentary additional accounts may not automatically include the EA add-on.","source_url":"https://help.fundednext.com/en/articles/8020763-is-ea-allowed-in-fundednext","checked_on":"2026-10-02"}],"fundingpips-fx-cfd":[{"title":"Zero: winning positions cannot offset open risk","scope_text":"FundingPips Zero only","calculation":"Only losing open positions are summed, with a cap of 1% of initial capital. Profits on other positions cannot offset this loss. The loss-limit baseline that trails profits does not reset after a reward payout.","consequence":"Zero consistency and payout-buffer conditions must also be met.","source_url":"https://help.fundingpips.com/hc/en-us/articles/34502157694865-FundingPips-Zero","checked_on":"2026-10-05"},{"title":"Zero: holding through news or weekends can terminate the account","scope_text":"FundingPips Zero only","calculation":"Opening, closing and holding are prohibited within 10 minutes before and after specified major releases. For major speeches, the window runs from 10 minutes before the start to 10 minutes after the end. All positions, including crypto, must be closed for the weekend.","consequence":"These are hard breaches causing immediate account termination. Avoiding new orders during news alone is insufficient.","source_url":"https://help.fundingpips.com/hc/en-us/articles/34502157694865-FundingPips-Zero","checked_on":"2026-10-05"},{"title":"Zero payouts require distributed profits and a 3% buffer","scope_text":"FundingPips Zero payout conditions","calculation":"The best day must account for no more than 15% of total profits. Seven days with profits of at least 0.25% of initial capital are required within 30 days. The first 3% profit is not withdrawable, and the largest losing trade must not exceed the largest winning trade.","consequence":"Failure to meet the 15% consistency condition postpones payout requests until it is met. This is distinct from termination for news or weekend breaches.","source_url":"https://help.fundingpips.com/hc/en-us/articles/34502157694865-FundingPips-Zero","checked_on":"2026-10-05"}],"e8-fx-cfd":[{"title":"More than 50% of trades lasting under 1 minute is prohibited","scope_text":"Applicable Classic Markets and Perpetual Futures trading policies","calculation":"The test uses the number of trades closed in under 1 minute, not average holding time. More than 50% is prohibited. Multiple users running the same EA strategy may also cause issues.","consequence":"After prohibited behavior is detected, risk may be restricted to 1% per idea/time frame. Additional history or interviews may be requested, with rewards held or accounts terminated.","source_url":"https://help.e8markets.com/en/articles/6929927-trading-policies-and-prohibited-trading-strategies","checked_on":"2026-10-05"},{"title":"Pro also caps the profits counted per day","scope_text":"E8 Pro evaluation and funded stages","calculation":"The daily counted-profit cap is 2% of initial capital. After passing, up to half of profits can be requested for payout, then the profit split is applied.","consequence":"The first payout also raises the loss floor to the initial balance under the applicable conditions; all profits cannot be freely withdrawn.","source_url":"https://help.e8markets.com/en/articles/15274219-e8-pro","checked_on":"2026-10-02"}],"alpha-fx-cfd":[{"title":"Re-entry within 10 minutes carries the prior loss forward","scope_text":"Qualified accounts purchased after the 2026-07-21 announcement","calculation":"Losing positions in the same instrument are combined; winning positions do not offset them. Limits are 3% for 5K/10K/25K, 2% for 50K/100K/200K and 1% for all Alpha Direct sizes. Re-entering the same instrument and direction within 10 minutes adds the prior loss.","consequence":"Reaching the threshold terminates the account and closes all positions. This is independent of daily and maximum DD.","source_url":"https://help.alphacapitalgroup.uk/en/articles/15888623-what-is-the-max-risk-rule-and-how-does-it-work","checked_on":"2026-10-05"},{"title":"Restricted group: 1% combined risk and halved lot limits","scope_text":"Accounts assigned to the Focused Trader Group","calculation":"Concurrent risk is capped at 1% of initial capital. Once cumulative losses on one instrument reach 1% that day, stop trading it until the next day. Lot limits are halved; EAs, merging and scaling are disabled.","consequence":"Leverage is also restricted. Removal from the group depends on review, including purchase date and payout history, rather than automatic reinstatement.","source_url":"https://help.alphacapitalgroup.uk/en/articles/9691161-focused-trader-group","checked_on":"2026-10-02"},{"title":"New trades recalculate withdrawal eligibility for remaining profits","scope_text":"Eligible On-demand accounts","calculation":"After a partial payout, starting new trades begins a new consistency period. Carried-over profits are excluded from its denominator.","consequence":"Remaining profits may become unavailable until the new conditions are met. Direct has separate buffer conditions.","source_url":"https://help.alphacapitalgroup.uk/en/articles/10102634-on-demand-performance-fee","checked_on":"2026-10-02"}],"fxify-fx-cfd":[{"title":"Shared EAs and cross-account offsets are also prohibited","scope_text":"Evaluation and funded accounts covered by the official prohibited-strategy guide","calculation":"Coordinating trades through the same EA across users, opposite positions across accounts, account management by others, delayed feeds and flooding the order book are prohibited. HFT is described as high-speed algorithmic trading; no universal minimum holding time in seconds is specified.","consequence":"Consequences include voiding breaching profits, rejecting an evaluation pass, or terminating the account or contract.","source_url":"https://fxify.com/blog/fxifys-prohibited-strategies/","checked_on":"2026-10-05"},{"title":"Pro caps daily profits and the first two payouts","scope_text":"Two Phase Pro","calculation":"Daily profits are capped at USD 4,000. Each of the first two payouts is capped at the smaller of 5% of initial capital or USD 8,000.","consequence":"General statements of no payout cap do not apply to Pro. Copy trading is also prohibited, unlike some other evaluation models.","source_url":"https://intercom.help/fxify/en/articles/14834005-the-2-phase-pro-account","checked_on":"2026-10-02"},{"title":"Instant requires closing all positions before the weekend","scope_text":"Instant Standard, Lite and Educational Instant","calculation":"Close all positions by Friday 15:45 EST. Restrictions also apply within 5 minutes before and after news, and EAs and copying are prohibited.","consequence":"Relying on automatic closure can still result in a DD breach. Distinguish this from overnight/weekend permissions for Crypto Instant or ordinary evaluation plans.","source_url":"https://intercom.help/fxify/en/articles/14938608-the-instant-funding-standard-account","checked_on":"2026-10-02"}],"blueguardian-fx-cfd":[{"title":"Over 80% margin usage and shared devices affect payout review","scope_text":"CFD evaluation and funded stages","calculation":"Margin usage above 80% while trading can be classified as gambling. Devices, VPSs or similar environments linked to multiple traders must not be shared. At least one trade is required within 30 days.","consequence":"Possible consequences include payout refusal, profit removal and account termination. Breaches may be detected in manual payout review rather than immediately when trading.","source_url":"https://help.blueguardian.com/en/articles/9661512-prohibited-trading-practices-account-policies","checked_on":"2026-10-05"},{"title":"Shield lowers the split to 50%; a second trigger terminates the account","scope_text":"Instant Standard (1%); funded 1Step/2Step Standard (2%)","calculation":"Guardian Shield triggers at the applicable floating-loss limit. The first trigger permanently reduces the profit split to 50%; the second closes the account.","consequence":"The 1% threshold is not shared by all plans. Do not apply these thresholds to Nano or other models.","source_url":"https://help.blueguardian.com/en/articles/14061082-instant-standard-account-rules","checked_on":"2026-10-02"},{"title":"2Step Nano caps payouts at 2%, even with more profits","scope_text":"Funded 2Step Nano","calculation":"Each payout cycle is capped at 2% of initial capital. Excess profits remain in the account.","consequence":"Failure to meet the profit-concentration condition holds eligibility until it is met; that alone does not cause immediate failure.","source_url":"https://help.blueguardian.com/en/articles/16445450-2-step-nano-rules","checked_on":"2026-10-02"}],"fundedelite-fx-cfd":[{"title":"Soft breaches can change the split and payout history","scope_text":"Funded-stage soft-breach handling","calculation":"Minimum-holding-time breaches and non-malicious IP/timing violations are reviewed. Consequences are not limited to warnings: the split may become 30% and the payout count may reset.","consequence":"This also affects the payout count used for refund eligibility. Repetition can lead to resets and forfeiture of current-period profits. An IP flag alone is not proof of misconduct.","source_url":"https://faq.fundedelite.com/en/articles/13868489-what-is-considered-a-soft-breach","checked_on":"2026-10-02"},{"title":"Losing trades can also breach the minimum holding time","scope_text":"Normally 3 minutes; 30 seconds with the purchased scalping add-on","calculation":"After passing, short-held losing trades are covered as well as winning trades. Review uses the dashboard scalping limit.","consequence":"Possible consequences include a reduced split, reset or forfeiture of the current payout.","source_url":"https://faq.fundedelite.com/en/articles/12675184-minimum-holding-time-for-the-trades","checked_on":"2026-10-02"}],"goat-fx-cfd":[{"title":"2% floating loss: 50% split first, termination next","scope_text":"Funded accounts under standard Goat Guard; excludes Instant, PayLater and Blitz","calculation":"Triggers when total floating loss reaches 2% of initial capital. After the first trigger, price changes alone on the unchanged set of positions do not trigger it again. Closing or opening trades changes that set; reaching the limit again then counts as another trigger.","consequence":"The first trigger keeps the account and positions open with a 50% split. The second permanently closes the account. Balance growth does not enlarge the 2% allowance.","source_url":"https://help.goatfundedtrader.com/en/articles/10742107-what-is-goat-guard","checked_on":"2026-10-05"},{"title":"Weekend holding may be allowed, but gap profits can be adjusted","scope_text":"Funded-stage weekend-gap policy","calculation":"Trades involving the period from 3 hours before Friday close to 3 hours after Monday open are reviewed. Applicable gap profits are removed.","consequence":"The policy states that this profit adjustment itself does not impose an account penalty. It is separate from general weekend-holding permission.","source_url":"https://help.goatfundedtrader.com/en/articles/14123389-do-you-allow-trading-the-weekend-gap","checked_on":"2026-10-02"}],"thinkcapital-fx-cfd":[{"title":"Overly wide SLs and abrupt strategy changes are reviewed","scope_text":"Official gambling/reckless-trading policy","calculation":"Review considers repeated risk above 2.5% or margin usage above 60–70%, among other factors. An overly wide SL may be problematic even if the trade closes at a small actual loss. More than 50 out of 100 trades lasting under 60 seconds is an excessive-scalping example.","consequence":"Warnings may be followed by restrictions, resets or termination; deliberate abrupt strategy changes may bypass warnings. Examples are not universal safe limits.","source_url":"https://www.thinkcapital.com/tc-faqs/general-faqs/what-are-thinkcapitals-guidelines-regarding-gambling-or-reckless-trading-behavior-on-the-platform/","checked_on":"2026-10-05"},{"title":"Concurrent use of one strategy across your own accounts is restricted","scope_text":"Published Challenge Agreement","calculation":"A clause prohibits simultaneously running the same strategy across multiple accounts you own.","consequence":"General EA permission does not establish copying permission. Separate funded-stage contracts and platform conditions also apply.","source_url":"https://www.thinkcapital.com/demo-agreement/","checked_on":"2026-10-03"}],"brightfunded-fx-cfd":[{"title":"Grid trading, excessive risk and account rolling are prohibited","scope_text":"Official prohibited-strategy policy","calculation":"Prohibited practices include hedging correlated instruments across accounts, exploiting delayed feeds or pricing errors, grid/tick/HFT trading, excessive leverage or correlated exposure, and repeatedly replacing failed accounts.","consequence":"Consequences include account termination or disqualification from future evaluations. Check the separate conditions governing EA use.","source_url":"https://help.brightfunded.com/en/articles/9241704-which-strategies-are-prohibited-at-brightfunded","checked_on":"2026-10-05"},{"title":"News breaches remove profits but retain losses","scope_text":"Funded stage; affected instruments within 5 minutes before/after major releases","calculation":"Openings and closings, including SL/TP and pending-order executions, are covered. Holding or modifying an order alone is distinct. A TP exception applies to trades held for at least 48 hours.","consequence":"This is a soft breach with profits deducted and losses retained. Do not extend the 48-hour exception to every closing method.","source_url":"https://help.brightfunded.com/en/articles/9241694-can-i-trade-news","checked_on":"2026-10-02"},{"title":"60 seconds is a trading-day counting condition","scope_text":"Required trading days during evaluation","calculation":"For a day to count, it must include a trade held for at least 60 seconds.","consequence":"This is not a universal minimum holding time, nor does it mean every trade under 60 seconds immediately fails the account.","source_url":"https://help.brightfunded.com/en/articles/9241611-what-are-the-current-rules-for-the-evaluation-process","checked_on":"2026-10-02"}],"fundedtradingplus-fx-cfd":[{"title":"Margin ratios trigger manual review, not automatic failure","scope_text":"At evaluation completion, scaling and funded-stage payouts","calculation":"Depending on account size, margin usage of 50–75% triggers manual review. Trade timing, correlation, volatility and prior warnings are assessed together.","consequence":"Exceeding the threshold alone is not failure. Review may clear trading considered appropriate, including diversification. Lot size or profit alone is not a universal disqualification condition.","source_url":"https://help.fundedtradingplus.com/risk-review-policy/","checked_on":"2026-10-05"},{"title":"Classic: a 3% loss on one instrument is a hard breach","scope_text":"Classic only","calculation":"Positions in the same instrument are combined. The test is a 3% equity loss (balance plus floating P/L) relative to the specified daily reference balance.","consequence":"Unlike a hold for missing the 35%/50% profit-concentration condition, this instrument loss limit is a hard breach.","source_url":"https://help.fundedtradingplus.com/2-step-classic-program-information/","checked_on":"2026-10-02"}],"instantfunding-fx-cfd":[{"title":"Re-entering within 10 minutes does not reset the 1% risk allowance","scope_text":"IF Micro PRO only","calculation":"Open trades in the same instrument and direction form one idea. Risk/loss above 1% of initial capital is prohibited; re-entry in the same direction within 10 minutes of closing remains the same idea. The HFT section prohibits trades lasting 60 seconds or less.","consequence":"The 1% rule is a hard breach. Maximum-lot violations cause a full reset. Payouts also require 5% profit on initial capital and a 15% Best Day limit (20% with the applicable add-on).","source_url":"https://instantfunding.com/help/if-micro/","checked_on":"2026-10-05"},{"title":"Evolve applies the split after the cap and ends after five payouts","scope_text":"Funded IF Evolve","calculation":"The requested amount is capped at the smaller of 50% of profit or USD 2,000. The 80% split is then applied: a USD 2,000 request pays USD 1,600.","consequence":"Day-count and consistency conditions must be met again each cycle. The account ends with the fifth payout.","source_url":"https://instantfunding.com/help/what-is-a-profit-cap/","checked_on":"2026-10-02"}],"tradingpit-fx-cfd":[{"title":"Larger Instant accounts cap potential losses at 0.5%","scope_text":"CFD Instant Earning Account only","calculation":"All open positions in one instrument are combined. With an SL, use the potential loss to that SL; without one, use worst-case price risk. The cap is 1% of initial capital for 5K–20K and 0.5% for 50K–100K.","consequence":"The first two occurrences automatically close positions but retain the account. The third is a hard breach ending it. This does not apply to other evaluation plans.","source_url":"https://support.thetradingpit.com/cfds-instant-max-position-loss","checked_on":"2026-10-05"},{"title":"Instant applies the split after limiting requests to half of profits","scope_text":"CFD Instant Earning Account","calculation":"Requests are capped at the smaller of 50% of profit or USD 2,500, then the 80% split applies. The official example: USD 6,000 profit permits a USD 2,500 request and USD 2,000 receipt.","consequence":"This does not permit requesting all profits. Futures payout caps are separate.","source_url":"https://support.thetradingpit.com/what-is-the-payout-policy-for-cfds-instant","checked_on":"2026-10-02"},{"title":"Some Instant instruments cannot be held over weekends","scope_text":"CFD Instant weekend holding","calculation":"Commodities, energy, metals and crypto are exceptions: positions are automatically closed 10 minutes before their Friday session ends.","consequence":"Do not extend general weekend-holding permission to every instrument.","source_url":"https://support.thetradingpit.com/is-weekend-holding-allowed-on-cfds-instant","checked_on":"2026-10-02"}],"fintokei-fx-cfd":[{"title":"Risk can link trades that do not overlap directly","scope_text":"Official maximum-open-risk rules","calculation":"Realized and unrealized losses are tested against a 3% cap both for same-instrument/same-direction ideas and for groups of overlapping trades. If A overlaps B and B overlaps C, A and C belong to the same group even without direct overlap.","consequence":"Exceeding the limit breaches the guidelines. Slippage and account-currency conversion affect the test. Scaled capital is included in the initial-capital reference. The recommended 0.5–1% is separate from the maximum.","source_url":"https://support.fintokei.com/en/articles/11315976-what-is-the-maximum-risk-on-open-trades","checked_on":"2026-10-05"},{"title":"CR designation changes risk, split and leverage","scope_text":"When individually placed under Consistency Rules","calculation":"CR1: 1% risk and a 15-percentage-point split reduction. CR2 includes 1% risk, a 1% daily counted-profit cap, 10:1 FX/5:1 other leverage and a 30-percentage-point split reduction.","consequence":"This may affect current and future accounts, even within basic DD limits. Removal is subject to review over periods such as 3–6 months. These are not the initial conditions for every account.","source_url":"https://support.fintokei.com/en/articles/11315966-consistency-rules-most-common-application","checked_on":"2026-10-02"}],"fundingtraders-fx-cfd":[{"title":"Re-entry within 5 minutes of a loss is reviewed under RMG","scope_text":"Funded-stage RMG; evaluation history also informs the starting tier","calculation":"New trades within 5 minutes after a 0.5% loss meet the Revenge criterion even on another instrument. Overlapping or within-2-minute same-instrument/same-direction trades are combined against a 2% planned-SL-risk criterion. Protective measures impose 1% risk, 30% margin and mandatory SLs.","consequence":"Escalation progresses through a warning, 70% split plus 50% deduction of breaching profits, 60% split plus full deduction, then termination at stage four. A flag is not itself a strike; review decides. Separate hard breaches may cause immediate termination.","source_url":"https://fundingtraders.com/help/en/articles/11927126-risk-management-at-fundingtraders","checked_on":"2026-10-05"},{"title":"Holding time uses a volume-weighted average","scope_text":"General trading policy; separate funded-stage HFT conditions","calculation":"Sum holding minutes multiplied by volume, then divide by total volume. The required average is at least 2 minutes. This is neither a simple average nor a requirement that every trade last 2 minutes.","consequence":"Funded-stage rules also address repeated HFT trades lasting 15 seconds or less. A single short trade does not necessarily receive the same treatment.","source_url":"https://fundingtraders.com/help/en/articles/12838492-general-trading-guidelines","checked_on":"2026-10-03"},{"title":"Failure within 48 hours of a payout request can cancel it","scope_text":"Applicable funded 1Step/2Step accounts","calculation":"A rule allows cancellation if the account fails within 48 hours after the request; the requested amount is returned to the account.","consequence":"Acceptance of a request is distinct from a finalized transfer.","source_url":"https://fundingtraders.com/help/en/articles/13399206-2-step-pro","checked_on":"2026-10-02"}],"propr-onchain":[{"title":"Strategy freedom does not permit cross-account offsets or payout/DD manipulation","scope_text":"All evaluation and funded accounts covered by the official rulebook","calculation":"Prohibited practices include opposite positions across Propr accounts or external CEXs/DEXs, coordination with others, repeatedly buying evaluations for maximum-risk binary bets, and exploiting the relationship between payouts and the DD floor.","consequence":"Trading/payouts may be suspended during investigation and additional records requested. Permanent termination without payout and exclusion from future use are possible. The rulebook states decisions are not appealable.","source_url":"https://www.propr.xyz/rules","checked_on":"2026-10-05"},{"title":"Payouts settle all profits; close positions before requesting","scope_text":"Official rulebook payout conditions","calculation":"Profits are settled in full rather than through partial payouts. All positions must be closed when requesting.","consequence":"The stated 24 hours is a processing timeframe, not guaranteed arrival of funds.","source_url":"https://www.propr.xyz/rules","checked_on":"2026-10-03"}],"hypernova-onchain":[{"title":"Permission to automate does not extend to third-party signals","scope_text":"Evaluation and funded accounts under the official rulebook","calculation":"Automating your own trading is distinguished from relying on third-party or community signals. Cross-account hedging and substantive strategy changes from evaluation to funded trading are prohibited practices.","consequence":"Equity (balance plus floating P/L) reaching the loss floor causes a permanent breach. Multiple accounts involving family members or shared devices/IPs require approval under the applicable conditions.","source_url":"https://hypernova.xyz/rulebook","checked_on":"2026-10-05"},{"title":"Reaching the profit target also triggers automatic closure","scope_text":"Evaluation-account profit target","calculation":"When equity (balance plus floating P/L) reaches the target, positions are automatically closed and passing is assessed.","consequence":"You may not be able to keep positions open to extend profits. The maximum loss floor is also tested against equity.","source_url":"https://hypernova.xyz/rulebook","checked_on":"2026-10-02"}],"fundedhive-onchain":[{"title":"Risk on one trading intent stays combined until fully closed","scope_text":"Terms 9.2.3 aggregation and 9.2.4 funded cross-account restrictions","calculation":"Multiple entries in the same instrument with the same intent are treated together until all are closed; additional orders do not reset risk. Overlapping trades in the same instrument across funded accounts sharing a user/IP/network are prohibited practices.","consequence":"On another funded account linked by user, IP or network, do not open that instrument until all positions in it on the original account are closed. Opposite directions are also covered. Suspension or termination may result.","source_url":"https://fundedhive.com/static/assets/download/terms-and-conditions.pdf?t=1743541676#page=30","checked_on":"2026-10-05"}],"pipfarm-fx-cfd":[{"title":"The risk period ends only after 60 continuous minutes flat","scope_text":"Accounts subject to Max Risk; limits and consequences vary by program","calculation":"A date change or closing one trade does not reset the period. Until all positions have been closed for 60 continuous minutes, realized and floating losses are tracked from the peak realized balance. Initial capital defines the allowance.","consequence":"At the threshold, all positions close automatically. Pip Protector programs record a strike and halve the limit; absolute-limit programs immediately breach the account. Check your contracted program.","source_url":"https://pipfarm.featurebase.app/en/help/articles/4175695-max-risk","checked_on":"2026-10-05"},{"title":"Infinity does not necessarily make funded accounts permanent","scope_text":"Applicable products/time-extension add-ons from 2026-04-09","calculation":"Infinity removes the evaluation time limit. The funded-account lifespan of 360 days and separate payout-eligibility periods remain.","consequence":"This is also separate from the 28-day inactivity condition. Check expiry and scaling-related extensions for your contracted product.","source_url":"https://help.pipfarm.com/en/help/articles/3206378-extended-time-limit-add-on","checked_on":"2026-10-02"},{"title":"PWP fees can leave the first payout at zero","scope_text":"Pay With Profits","calculation":"The funded-stage fee is deducted from the first gross request, then the profit split applies to the remainder. Official example: 100K Very High, USD 3,000 request minus USD 3,000 fee equals zero cash received.","consequence":"The first requested amount differs from the amount received. Risk-tier fees are not included in the entry fee.","source_url":"https://help.pipfarm.com/en/help/articles/8246911-pay-with-profits-payouts","checked_on":"2026-10-02"},{"title":"Split closures to manufacture days or consistency are prohibited","scope_text":"Policy against manipulating trading metrics","calculation":"Review covers spreading partial closes or re-entries across days to artificially meet profitable-day or consistency requirements.","consequence":"Depending on intent and pattern, consequences include a retry, profit removal or failure. This is not a blanket ban on ordinary partial closures.","source_url":"https://help.pipfarm.com/en/help/articles/2645328-manipulating-program-rules","checked_on":"2026-10-03"}],"fundedtradermarkets-fx-cfd":[{"title":"Close the remainder of a partially closed position that day","scope_text":"General trading rules; consequences vary by stage","calculation":"Carrying the remainder into the next day is prohibited. Multiple entries in one instrument within 15 minutes are aggregated. Funded trades lasting under 1 minute also have profits excluded.","consequence":"Breaching profits are deducted. Evaluation rules can require a retry if breaching profits exceed 20%. For 2Step short trades, the denominator is the combined profit target of both stages.","source_url":"https://www.fundedtradermarkets.com/faq/category/general-trading-rules","checked_on":"2026-10-05"},{"title":"2Step Plus Shield also reduces the profit split","scope_text":"Funded 2-Step Plus, basic conditions","calculation":"When floating loss exceeds 1% of balance, positions close automatically and the split drops through 50%, 40%, 30% and 20%. The fourth occurrence fixes the split at 20%.","consequence":"Manual closure and slippage may still be covered. With the 90% add-on this also applies during evaluation: the first breach allows continuation, the second fails evaluation.","source_url":"https://www.fundedtradermarkets.com/faq/category/2-step-plus-evaluation","checked_on":"2026-10-05"}],"funded7-fx-cfd":[{"title":"Large-trade concentration and profit distribution are reviewed","scope_text":"Rule 1; post-evaluation/payout eligibility","calculation":"Maximum trade volume is the smaller of median volume × 2.5 and Q3 + 1.5 × IQR. Q3 is the 75th percentile; IQR spans the 25th to 75th percentiles. At least 10 closes and 3 active days are required. The sum of the second- and third-largest profits divided by the largest must be at least 0.9. Nearby trades in one instrument are grouped.","consequence":"Missing this condition alone does not count as a strike. Treatment differs by stage: transition to Silver after Phase 2, or payout holds on Pro until conditions are met, among others.","source_url":"https://funded7.com/faq/rule-1-payout-criteria/","checked_on":"2026-10-05"},{"title":"Short trades are tested by seconds and trade-count ratios","scope_text":"Accounts subject to Rule 3","calculation":"A breach occurs when closes under 15 seconds exceed 2% of all trades, or closes under 30 seconds exceed 3%. Average holding time is not used.","consequence":"Profits from breaching trades are removed while losses remain. Serious/repeated breaches can demote the account to Silver/Bronze with tighter restrictions.","source_url":"https://funded7.com/faq/rule-2-3-position-risk-execution/","checked_on":"2026-10-05"},{"title":"Risk review includes SL distance, correlation and total exposure","scope_text":"Funded / Silver Funded / Bronze Funded","calculation":"Risk caps are 3% / 2% / 1%, respectively, tested for each trade, correlated group and all positions combined. The widest SL distance used during the trade is also considered.","consequence":"Silver/Bronze require SLs. Without an SL, ATR-based risk assessment means a small actual loss does not establish compliance. Manipulating SLs to evade limits can cause immediate termination.","source_url":"https://funded7.com/faq/rule-2-3-position-risk-execution/","checked_on":"2026-10-05"},{"title":"Copying between your own accounts and adding to losers are restricted","scope_text":"Rule 4 prohibited strategies","calculation":"Increasing lot size when adding to a losing trade is prohibited. Averaging with equal or smaller size within risk limits is distinguished. Copying between your own Funded7 accounts is also prohibited.","consequence":"Third-party signals and off-the-shelf EAs producing identical trades are also covered. Prohibited practices can cause immediate termination and profit forfeiture.","source_url":"https://funded7.com/faq/rule-4-prohibited-strategies-fair-play/","checked_on":"2026-10-02"}],"tradingcult-fx-cfd":[{"title":"Pay After Pass has short-trade and profit-concentration rules","scope_text":"Funded Pro TradingCult Pay After Pass accounts","calculation":"The account closes if the largest trade or day exceeds 25% of total profits for 1Step or 30% for 2Step. Minimum holding time is 30 seconds: first breach warns, second closes the account.","consequence":"Payouts require 5 days each earning at least 1%. These conditions differ from ordinary TradingCult accounts.","source_url":"https://faq.es.tradingcult.com/que-es-el-pay-after-pass-challenge/","checked_on":"2026-10-05"}],"blueberry-fx-cfd":[{"title":"Self-developed EAs also need prior approval","scope_text":"Officially stated EA requirements apply to all accounts regardless of purchase date","calculation":"The EA must be self-developed, implement your own strategy/risk decisions, and be disclosed and approved in advance. Outsourced development is prohibited as well as commercial/free distributed EAs. Changing settings alone does not make it self-developed.","consequence":"Violations may end the account and forfeit unpaid rewards. Other prohibitions differ around March 12, so older accounts must not be assumed fully subject to relaxed terms.","source_url":"https://help.blueberryfunded.com/en/articles/9714626-prohibited-strategies-after-march-12-2026","checked_on":"2026-10-05"},{"title":"Flex: exceeding 1% does not always mean a first warning","scope_text":"Flex 1-Step evaluation and funded stages","calculation":"Floating loss above 1% first closes positions and, on the second occurrence, closes the account. The counter resets after passing. However, aggregating realized losses through re-entry within 10 minutes can directly cause a hard breach.","consequence":"The separate news-breach counter carries from evaluation into the funded stage; do not confuse the two.","source_url":"https://help.blueberryfunded.com/en/articles/16436967-what-is-the-soft-breach-on-flex-1-step-accounts","checked_on":"2026-10-03"},{"title":"Flex profit concentration can add days before the first payout","scope_text":"At passing Flex evaluation","calculation":"If one idea produces more than 60% of the evaluation target, a 4-day condition is added before the first payout.","consequence":"This is a one-time test, distinct from recurring Best Day consistency or immediate failure for excess concentration.","source_url":"https://help.blueberryfunded.com/en/articles/9812246-does-blueberry-funded-enforce-a-consistency-rule-in-trading","checked_on":"2026-10-02"}],"fundora-fx-cfd":[{"title":"1% risk and frequent trades closed within 20 seconds are reviewed","scope_text":"Official risk guidance, starting from challenge stages","calculation":"Even a temporary loss exceeding 1% of available margin balance can be reviewed. Examples include concurrent correlated positions and trading without SLs. Frequent closes within 20 seconds may lead to warnings or failure.","consequence":"A first warning is not guaranteed. Similar behavior after a warning can lead to failure/termination, with no refund or compensation for the relevant failure.","source_url":"https://fundora-trading.com/en/blog/interpretations-and-definitions-regarding-the-criteria-for-1-risk-trading-and-scalping-within-20-seconds","checked_on":"2026-10-05"},{"title":"Merging accounts resets payout dates and achievement counts","scope_text":"Approved Pro-account mergers","calculation":"The merged account is new: scheduled payout date, required days, consistency and payout count all reset.","consequence":"Previously satisfied conditions do not simply carry over. Eligibility to apply depends on conditions such as balances and pending payouts.","source_url":"https://fundora-trading.com/en/blog/rules-and-conditions-for-multiple-account-merging","checked_on":"2026-10-02"}],"monetafunded-fx-cfd":[{"title":"New Instant: the 1% floating-loss limit is a hard breach","scope_text":"Instant Funding purchased from 2026-09-21; excludes Instant Funding Pro","calculation":"Maximum floating loss is 1% of initial capital. Distinguish this from other models with 2%/3% thresholds or a 1.5% idea restriction after a warning.","consequence":"The applicable new-Instant threshold causes an immediate breach.","source_url":"https://help.monetafunded.com/en/articles/17018053-max-floating-loss-allowed-on-funded-accounts","checked_on":"2026-10-05"},{"title":"After a warning, risk per idea is restricted to 1.5%","scope_text":"Funded 2-Step accounts with 5% or 4% daily-loss limits","calculation":"The 5%-daily type warns at 3% floating loss; the 4%-daily type at 2%. Close all positions and stop until 22:00 UTC; thereafter each idea is capped at 1.5%.","consequence":"Exceeding 1.5% fails the affected account. Removal guidance refers to 14 days and 20 trades on another funded account, not automatic removal.","source_url":"https://help.monetafunded.com/en/articles/17018053-max-floating-loss-allowed-on-funded-accounts","checked_on":"2026-10-02"}],"superfunded-fx-cfd":[{"title":"Planned SL risk, simultaneous losses and lot-size multiples are reviewed","scope_text":"Official FAQ gambling policy","calculation":"Review covers planned loss to SL or realized loss exceeding 2.5% of balance (simultaneous positions combined), concentrated trades with overly distant/no SLs, and concurrent lots above twice the usual average, among other patterns.","consequence":"Measures include email warnings, removing breaching profits, mandatory SLs on new orders and extending profit caps for three additional payouts. Further violations can terminate the account and contract.","source_url":"https://superfunded.com/faqs/","checked_on":"2026-10-05"},{"title":"Excess daily profit is deducted from payout requests","scope_text":"Official FAQ funded-stage payout conditions","calculation":"One day can contribute up to 40% of the requested amount, or 30% for initial capital of USD 50,000 or more. Profits from split closures are assigned to the day of final closure.","consequence":"Excess is deducted from the request. This differs from consistency rules under which increasing profits can make the whole amount eligible later.","source_url":"https://superfunded.com/faqs/","checked_on":"2026-10-05"},{"title":"First three payouts have a profit cap with no excess carryover","scope_text":"Funded One Phase and Two Phase started from 2025-09-10","calculation":"One Phase: 5% for all account sizes. Two Phase started from 2025-09-10: also 5% for all sizes. The cap applies before the profit split.","consequence":"Applies to the first three payouts. Profits above the cap are not paid or carried to the next payout.","source_url":"https://superfunded.com/faqs/","checked_on":"2026-10-05"}],"hantec-fx-cfd":[{"title":"Risk-management groups restrict trading conditions","scope_text":"Current and future funded accounts; excludes Challenge accounts","calculation":"Repeated risk above 3% (1% for Lite), scalping under 3 minutes and account rolling are reviewed and may lead to restrictions such as reduced leverage.","consequence":"Review can follow three completed payouts on the same account. Meeting that condition does not automatically remove restrictions.","source_url":"https://htrader.freshdesk.com/en/support/solutions/articles/158000444270-what-is-the-risk-management-group-","checked_on":"2026-10-05"},{"title":"Restricted groups reduce metals leverage to 1:3","scope_text":"Funded accounts in the Risk Management Group","calculation":"Leverage is restricted to FX 1:30, indices/commodities 1:5, metals 1:3 and crypto 1:1. Future funded accounts may also be affected. Challenge accounts are excluded.","consequence":"After three successful payouts on the same account, you may ask support to review removal. Three payouts do not automatically remove restrictions.","source_url":"https://htrader.freshdesk.com/en/support/solutions/articles/158000444270-what-is-the-risk-management-group-","checked_on":"2026-10-05"},{"title":"Scalping review when under-3-minute trades produce at least 30% of net profit","scope_text":"Official scalping policy","calculation":"Applies when net profit from trades closed in under 3 minutes is at least 30% of total net profit over the assessment period. This is not a trade-count ratio or average holding time.","consequence":"Possible consequences include profit reduction/removal, restrictions, suspension or termination.","source_url":"https://help.htrader.hmarkets.com/en/support/solutions/articles/158000444299-scalping","checked_on":"2026-10-02"},{"title":"Instant24 treats additional positions and risk breaches differently","scope_text":"Instant24","calculation":"Only one position may be open at a time. Additional positions are automatically closed as a soft breach allowing account continuation. Open risk above 1% of initial capital is instead a hard breach.","consequence":"Automatic closure of an extra position is distinct from account failure for exceeding the risk cap.","source_url":"https://help.htrader.hmarkets.com/en/support/solutions/articles/158000445803-instant24","checked_on":"2026-10-02"}],"icfunded-fx-cfd":[{"title":"Instant automatically fails at 1.5% loss per idea","scope_text":"Instant","calculation":"Concurrent trades such as those in the same asset and direction are combined as one idea. Loss is capped at 1.5% of real-time balance.","consequence":"Splitting orders does not create separate allowances. This differs from the 1.5% review guideline for evaluation models.","source_url":"https://www.icfunded.com/rules","checked_on":"2026-10-05"},{"title":"Instant also has a 75% margin-exposure criterion","scope_text":"Instant","calculation":"Margin exposure must stay below 75% of real-time balance.","consequence":"Exceeding the criterion automatically fails the account. Oversized positions can breach rules even within DD limits.","source_url":"https://www.icfunded.com/rules","checked_on":"2026-10-05"},{"title":"News restrictions differ between evaluation models and Instant","scope_text":"Funded evaluation-model accounts / Instant","calculation":"After evaluation, opening/closing is restricted within 3 minutes before and after affected releases. Instant positions must close at least 10 minutes before; no trading within 10 minutes before/after. US CPI, PCE, NFP and FOMC restrictions on Instant cover all assets.","consequence":"Permission to trade news during evaluation does not extend to funded accounts or Instant.","source_url":"https://www.icfunded.com/rules","checked_on":"2026-10-05"},{"title":"Evaluation models: 1.5% is a review guideline, not automatic failure","scope_text":"1-Step / 2-Step","calculation":"Risk per trading idea should remain within 1.5% of balance.","consequence":"This alone is not an automatic-failure condition, but can be considered in reviews of excessive risk or concentration.","source_url":"https://www.icfunded.com/rules","checked_on":"2026-10-05"},{"title":"No weekend holding; 30 days inactive can end an account","scope_text":"All listed plans","calculation":"Overnight holding is allowed, but positions must close before Friday market close. Accounts with no trades for 30 days may be suspended or terminated.","consequence":"Unnatural tiny trades solely to meet minimum-day requirements are also prohibited practices.","source_url":"https://www.icfunded.com/rules","checked_on":"2026-10-05"},{"title":"HFT, copying, risk offsets and abrupt strategy changes are reviewed","scope_text":"Evaluation and funded stages","calculation":"Prohibited practices include HFT/tick scalping, offsetting risk with other accounts, martingale/grid loss recovery and unnatural strategy changes from evaluation to funded trading.","consequence":"Profits may be excluded, payouts withheld or accounts terminated. The terms also allow discretionary review of practices not listed.","source_url":"https://www.icfunded.com/terms-and-conditions","checked_on":"2026-10-05"}]}[id]||[]);return scopedRows1019(id,base209).map(r=>'<details'+(r.rule_id?' id="rule-'+esc(r.rule_id)+'" data-rule-id="'+esc(r.rule_id)+'"':'')+' class="scoped-special-v202"><summary class="scoped-rule-heading"><span>'+labels[0]+'</span><h4>'+esc(r.title)+'</h4></summary><p class="scoped-rule-scope">'+labels[1]+': '+esc(r.scope_text)+'</p><dl><div><dt>'+labels[2]+'</dt><dd>'+esc(r.calculation)+'</dd></div><div><dt>'+labels[3]+'</dt><dd>'+esc(r.consequence)+'</dd></div></dl><p class="scoped-rule-source"><a target="_blank" rel="noopener noreferrer" href="'+esc(r.source_url)+'">'+labels[4]+' ↗</a><span>'+labels[5]+' '+esc(r.checked_on)+'</span>'+(r.related_sources||[]).map((u,k)=>' <a target="_blank" rel="noopener noreferrer" href="'+esc(u)+'">Related official source '+(k+1)+' ↗</a>').join('')+'</p></details>').join('');}


function hiveExtra209(id){return id==="fundedhive-onchain"?"<details class=\"scoped-special-v202\"><summary>AADS: −1% triggers a switch to B-Book</summary><p>Funded accounts subject to AADS. A loss of 1% of the initial balance closes all positions and switches the account to internal B-Book simulation. This is separate from maximum drawdown. B-Book profits cannot be withdrawn as cash. Once the balance recovers to at least the initial balance, manually select “Activate A-Book”; the restart resets the balance to its initial level. Earlier A-Book losses remain to be offset by new A-Book profits. Positions also close automatically when the loss-offset profit target is reached.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://fundedhive.com/static/assets/download/terms-and-conditions.pdf?t=1743541676#page=11\">Official terms</a> · 2026-10-05 · <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://note.com/regal_pika7669/n/n3e17d9e1811f\">More on NOTE (Japanese)</a></p></details><details class=\"scoped-special-v202\"><summary>HIVE coins and PONCHAI: challenge plans only</summary><p>INSTANT is excluded. Passing earns HIVE coins worth 200% of the purchase price; this is not a cash fee refund. Coins can cover up to 50% of a later purchase. At the same price and without another code, that is enough for four half-price purchases. PONCHAI gives 20% off the original price, with coins covering another 30% of the original price: a $100 plan can cost $50 in cash ($20 discount + $30 in coins). Check the final checkout conditions.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://fundedhive.com/static/assets/download/terms-and-conditions.pdf?t=1743541676#page=8\">Official terms</a> · 2026-10-05 · <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://note.com/regal_pika7669/n/n3e17d9e1811f\">More on NOTE (Japanese)</a></p></details>":"";}
const pendingPlanCompanies=new Map(), planErrors=new Set();
document.addEventListener('click',e=>{const b=e.target.closest('[data-plan-retry]');if(b){planErrors.delete(b.dataset.planRetry);renderDetail();}});
function e8TermsCaution20261019(id){return id==="e8-fx-cfd"?"<style>.e8-terms-caution-v20261019{margin:20px 0;padding:18px;border:1px solid #d8b56c;border-left:4px solid #b47e18;border-radius:10px;background:#fffaef;line-height:1.8}.e8-terms-caution-v20261019 p{margin:0}@media(max-width:600px){.e8-terms-caution-v20261019{padding:14px}}</style><div class=\"e8-terms-caution-v20261019\" role=\"note\"><p><strong>Note:</strong> E8 Markets’ terms of use (Section 6.5) say that features, prices and reward structures can be changed even after purchase, and Section 13 covers how changes apply to existing users and how they are notified. As of October 19, 2026, we have not found a case where an adverse change was actually applied to existing accounts, but please check the latest terms and the version that applies to your account before you buy.</p></div>":"";}
function planPanel(c){
 if(state.tab!=='plans')return '';
 if(planErrors.has(c.service_id))return '<section class="panel"><button data-plan-retry="'+esc(c.service_id)+'">Retry loading plans</button></section>';
 if(!fullPlanCompanies.has(c.service_id)){
  if(!pendingPlanCompanies.has(c.service_id)){
   pendingPlanCompanies.set(c.service_id,window.pcLoadCompanyPlans('en',c.service_id).then(rows=>{planData[c.service_id]=rows;fullPlanCompanies.add(c.service_id);renderDetail();}).catch(()=>{pendingPlanCompanies.delete(c.service_id);planErrors.add(c.service_id);renderDetail();}));
  }
  return '<section class="panel"><p role="status">Loading plans…</p></section>';
 }
 return '<section class="panel"><h3>Plans, rules and notes</h3><p>Plan filters do not change the overall reference score of a firm.</p>'+planNote()+e8TermsCaution20261019(c.service_id)+commonRules200(c.service_id)+scopedSpecial209(c.service_id)+hiveExtra209(c.service_id)+planMatrix(c.service_id)+'</section>';}
function initPlanFilters(){
 const saved=new URLSearchParams(location.search);['category','currency','capital'].forEach(k=>planChoice[k]=saved.get('plan_'+k)||'');planChoice.capital=planChoice.capital.replace(/^USD_display /,'USD ');if(!planChoice.currency&&planChoice.capital)planChoice.currency=planChoice.capital.split(' ')[0];
 const table=$('#comparison-table');if(!table){if($('#detail-root'))renderDetail();return;}
 const form=document.createElement('form');form.className='plan-filters-v168';form.innerHTML='<label>Plan category<select data-plan-filter="category"><option value="">All</option></select></label><label>Capital currency<select data-plan-filter="currency"><option value="">Select currency</option><option value="USD">USD</option><option value="JPY">JPY</option></select></label><label>Initial capital<select data-plan-filter="capital"><option value="">All</option></select></label><button type="reset">Reset plan filters</button>';
 const all=Object.values(planData).flat().filter(visiblePlan);
 const categorySelect=form.querySelector('[data-plan-filter="category"]');
 ['1STEP','2STEP','3STEP','INSTANT','合格後払い 1STEP','合格後払い 2STEP','合格後払い 3STEP','未確認'].filter(c=>all.some(p=>p.category===c)).forEach(c=>categorySelect.add(new Option(c.replace('合格後払い',"Pay after passing"),c)));
 const capitalSelect=form.querySelector('[data-plan-filter="capital"]');
 function refreshCapital(){capitalSelect.innerHTML='<option value="">'+(planChoice.currency?'All sizes':'Select currency first')+'</option>';capitalSelect.disabled=!planChoice.currency;[...new Set(all.filter(p=>p.initial_capital!=null&&capitalKey(p).startsWith(planChoice.currency+' ')).map(capitalKey))].sort((a,b)=>Number(a.split(' ')[1])-Number(b.split(' ')[1])).forEach(v=>{const [currency,amount]=v.split(' ');capitalSelect.add(new Option(amountLabel(amount,currency),v));});if([...capitalSelect.options].some(o=>o.value===planChoice.capital))capitalSelect.value=planChoice.capital;else planChoice.capital='';}
 refreshCapital();
 const wrapper=table.closest('.table-wrap')||table.parentElement;wrapper.before(form);
 form.querySelectorAll('select').forEach(s=>s.value=planChoice[s.dataset.planFilter]);
 form.onsubmit=e=>e.preventDefault();form.onchange=e=>{if(e.target.dataset.planFilter==='currency'){planChoice.currency=e.target.value;planChoice.capital='';refreshCapital();}form.querySelectorAll('select').forEach(s=>planChoice[s.dataset.planFilter]=s.value);renderComparison();if($('#detail-root'))renderDetail();};
 form.onreset=()=>{planChoice={category:'',currency:'',capital:''};setTimeout(()=>{refreshCapital();renderComparison();if($('#detail-root'))renderDetail();},0);};
 document.addEventListener('click',e=>{const a=e.target.closest('a.comparison-detail-link');if(a&&planActive()){const u=new URL(a.href);Object.entries(planChoice).forEach(([k,v])=>{if(v)u.searchParams.set('plan_'+k,v)});a.href=u.href;}});
 renderComparison();if($('#detail-root'))renderDetail();
}


window.pcDataRequest('/plan-options-v179-en.json').then(r=>r.json()).then(d=>{planData=d;return init()}).then(initPlanFilters);
